-- ============================================================
-- SEED EXT 6: Módulo 19 — Hedging Language (ex 208-300)
-- Blocos 71-81 | 93 exercícios
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'hedging-language';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo hedging-language não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Modal verbs como hedges (9 ex)
  (cid,71,208,'gap_fill','The evidence _____ (may/suggest) that the relationship between institutional design and governance outcomes is more complex than earlier models _____ (assume/past).','may suggest / assumed',NULL,'"May suggest" = epistemic modal hedge (possibility); "assumed" = past tense for contrast with present finding.','easy'),
  (cid,71,209,'gap_fill','These findings _____ (might/imply) that current regulatory frameworks _____ (be) insufficient to address the full range of challenges posed by digital platforms — a _____ (conclude/noun) that _____ (warrant) further investigation.','might imply / may be / conclusion / warrants',NULL,'"Might imply" = low-certainty modal; "may be" = epistemic possibility; "conclusion that warrants" = hedged assessment.','medium'),
  (cid,71,210,'gap_fill','The pattern _____ (could/reflect) deeper structural weaknesses, although alternative explanations _____ (cannot/rule out/passive) at this stage of the analysis.','could reflect / cannot be ruled out',NULL,'"Could reflect" = speculative modal; "cannot be ruled out" = epistemic caution through negation.','medium'),
  (cid,71,211,'gap_fill','This _____ (would/appear) to suggest that the relationship between economic growth and institutional quality _____ (be) bidirectional rather than unidirectional, though the direction of causality _____ (remain) difficult to establish with certainty.','would appear / may be / remains',NULL,'"Would appear to suggest" = double hedge (modal + appear); "may be" + "remains difficult" = layered hedging.','hard'),
  (cid,71,212,'gap_fill','Institutional reforms _____ (may/need) to be accompanied by cultural change if they _____ (be) to produce lasting improvements in governance quality — a _____ (suggest/noun) that _____ (have) significant implications for the pace of reform.','may need / are / suggestion / has',NULL,'"May need" = hedged necessity; "a suggestion that has implications" = hedged conclusion framing.','hard'),
  (cid,71,213,'gap_fill','The _____ (could/argue/passive) that the failure of previous reforms was due not to poor design but to insufficient attention to implementation — a _____ (possible/noun) that _____ (deserve) serious consideration despite its _____ (potentially → noun) controversial _____ (imply → noun).','it could be argued / possibility / deserves / potentially / implications',NULL,'"It could be argued that" = classic hedge phrase; "possibility" + "potentially controversial implications" = compounded hedging.','hard'),
  (cid,71,214,'gap_fill','While the evidence _____ (be/strong), it _____ (be) important to acknowledge that _____ (considerable/noun) _____ (uncertain → noun) _____ (remain) about the _____ (longer-term → noun) _____ (consequent → noun) of these _____ (find → noun).','may be strong / is / considerable / uncertainty / remains / longer-term / consequences / findings',NULL,'"May be strong" + "considerable uncertainty remains" = balanced hedging acknowledging strength while caveating.','hard'),
  (cid,71,215,'gap_fill','It _____ (might/be worth/note/passive) that the _____ (sample) used in this study _____ (may/not/fully/representative/be) of the _____ (broader) _____ (population), which _____ (could/limit) the _____ (generalize → noun) of the _____ (find → noun).','might be worth noting / sample / may not be fully representative / broader / population / could limit / generalizability / findings',NULL,'"Might be worth noting" + "may not be fully representative" + "could limit generalizability" = three-layer methodological hedge.','hard'),
  (cid,71,216,'multiple_choice','Which sentence uses modal hedging MOST appropriately for academic writing?','The results may suggest a positive relationship between transparency and public trust, though further research is needed.','["The results prove there is a relationship between transparency and trust.","The results may suggest a positive relationship between transparency and public trust, though further research is needed.","The results might possibly perhaps indicate something about transparency and trust.","The results definitely suggest a relationship between transparency and trust."]','Option B: single "may suggest" + qualifying clause = appropriate hedge. Option A (prove) overconfident. Option C is excessive hedging. Option D (definitely) removes hedge.','medium'),

  -- BLOCK 72: Epistemic adverbs como hedges (9 ex)
  (cid,72,217,'gap_fill','_____ (Argue/adverb), the most significant factor in determining reform outcomes is not the quality of institutional design but the political will to implement it — a _____ (contention) that _____ (remain) difficult to test _____ (directly).','Arguably / contention / remains / directly',NULL,'"Arguably" = epistemic adverb acknowledging contestability; "remains difficult to test" = methodological hedge.','medium'),
  (cid,72,218,'gap_fill','The data _____ (apparent/adverb) _____ (support) the hypothesis, _____ (although) closer _____ (examine → noun) _____ (reveal) several _____ (anomaly) that _____ (potentially → adverb) _____ (undermine) this _____ (initial → noun) _____ (assess → noun).','apparently / support / although / examination / reveals / anomalies / potentially / undermine / initial / assessment',NULL,'"Apparently" = hedge on data appearance; "potentially undermine" = epistemic caution about anomaly significance.','hard'),
  (cid,72,219,'gap_fill','_____ (Possible/adverb), the _____ (relationship) _____ (observe/passive) _____ (reflect) _____ (underlying) _____ (variable) that _____ (have) not _____ (include/passive) in the _____ (analysis) — a _____ (possibility) that _____ (cannot) be _____ (dismiss/passive) without _____ (further) _____ (investigate → noun).','Possibly / relationship / observed / reflects / underlying / variables / have / been included / analysis / possibility / cannot / dismissed / further / investigation',NULL,'"Possibly" hedges the interpretation; "cannot be dismissed without further investigation" = cautious epistemic stance.','hard'),
  (cid,72,220,'gap_fill','The reform _____ (presumably) _____ (proceed) on the _____ (assumption) that _____ (formal) _____ (rule) are self-enforcing — an _____ (assumption) that _____ (seem) _____ (likely) to prove _____ (over-optimistic/adverb) in light of _____ (available) _____ (evidence).','presumably / proceeded / assumption / formal / rules / assumption / seems / likely / overly optimistic / available / evidence',NULL,'"Presumably" = inferred assumption; "seems likely to prove overly optimistic" = hedged negative prediction.','hard'),
  (cid,72,221,'gap_fill','These _____ (finding → noun) are _____ (broadly → adverb) _____ (consistent) with _____ (existing) _____ (literature), _____ (although) _____ (notable) _____ (exception) _____ (exist) that _____ (suggest) the _____ (relationship) _____ (may) be _____ (more → adverb) _____ (contextually) _____ (dependent) than _____ (previously → adverb) _____ (believe/passive).','findings / broadly / consistent / existing / literature / although / notable / exceptions / exist / suggest / relationship / may / more / contextually / dependent / previously / believed',NULL,'"Broadly consistent" + "although notable exceptions exist" + "may be more contextually dependent than previously believed" = calibrated hedging.','hard'),
  (cid,72,222,'gap_fill','_____ (Apparent/adverb), _____ (institutional) _____ (reform) _____ (alone) is _____ (insufficient) to _____ (produce) _____ (sustainable) _____ (improvement) in _____ (governance) _____ (quality) — _____ (though) the _____ (precise) _____ (condition) _____ (under) _____ (which) _____ (it) _____ (succeed) _____ (remain) _____ (unclear).','Apparently / institutional / reform / alone / insufficient / produce / sustainable / improvement / governance / quality / though / precise / conditions / under / which / succeeds / remain / unclear',NULL,'"Apparently" hedges the general claim; "though the precise conditions remain unclear" adds a qualifying caveat.','hard'),
  (cid,72,223,'gap_fill','The _____ (tendency) of _____ (organization → noun) to _____ (revert) to _____ (established) _____ (practice) after _____ (initial) _____ (reform) _____ (effort) _____ (suggest) that _____ (sustain/gerund → noun) _____ (change) _____ (require) _____ (arguably) _____ (more) _____ (than) _____ (merely) _____ (new) _____ (formal) _____ (rule).','tendency / organizations / revert / established / practices / initial / reform / efforts / suggests / sustaining / change / requires / arguably / more / than / merely / new / formal / rules',NULL,'"Arguably" hedges normative claim; "suggests" hedges empirical claim; "tendency" itself is a hedging noun.','hard'),
  (cid,72,224,'gap_fill','_____ (Broad/adverb) _____ (speak), the _____ (field) has _____ (make/passive) _____ (progress) in _____ (understand/gerund) what _____ (drive) _____ (institutional) _____ (change), _____ (although) _____ (significant) _____ (gap) in _____ (knowledge) _____ (remain) and _____ (likely) _______ (will) _____ (persist) for some _____ (time).','Broadly / speaking / field / been made / progress / understanding / drives / institutional / change / although / significant / gaps / knowledge / remain / likely / will / persist / time',NULL,'"Broadly speaking" = limiting adverb; "although significant gaps remain and likely will persist" = two hedges.','hard'),
  (cid,72,225,'multiple_choice','Which epistemic adverb MOST appropriately hedges this claim? "_____, the direction of causality runs from institutional quality to economic development rather than the reverse."','Arguably','["Certainly","Arguably","Obviously","Undeniably"]','"Arguably" acknowledges the claim is debatable — the most appropriate hedge for a contested causal claim. The others remove or understate uncertainty.','easy'),

  -- BLOCK 73: Verb hedges — suggest, indicate, appear, seem, tend (9 ex)
  (cid,73,226,'gap_fill','The data _____ (suggest) that governance quality _____ (influence) economic outcomes, _____ (although) the _____ (magnitude) of this _____ (effect) _____ (appear) to _____ (vary) significantly _____ (across) _____ (context).','suggest / influences / although / magnitude / effect / appears / vary / across / contexts',NULL,'"Suggest" + "appear to vary" = double verb hedge; "although" introduces qualifying clause.','medium'),
  (cid,73,227,'gap_fill','The _____ (evidence) _____ (seem) to _____ (support) the _____ (view) that _____ (informal) _____ (norm) _____ (play) a more _____ (significant) _____ (role) than _____ (formal) _____ (structure) in _____ (determine/gerund) _____ (organizational) _____ (behave → noun).','evidence / seems / support / view / informal / norms / play / significant / role / formal / structures / determining / organizational / behavior',NULL,'"Seems to support" = hedged epistemic stance; "determining organizational behavior" = gerund-noun.','medium'),
  (cid,73,228,'gap_fill','Reform _____ (tend) to _____ (succeed) when _____ (it) _____ (accompany/passive) by _____ (sustained) _____ (political) _____ (will) — _____ (a) _____ (pattern) that _____ (emerge) _____ (consistently) _____ (across) _____ (the) _____ (case) _____ (study/passive) but _____ (that) _____ (does) _____ (not) _____ (guarantee) _____ (success) _____ (in) _____ (any) _____ (particular) _____ (instance).','tends / succeed / it / is accompanied / sustained / political / will / a / pattern / emerges / consistently / across / the / cases / studied / that / does / not / guarantee / success / in / any / particular / instance',NULL,'"Tends to succeed" + "pattern emerges consistently" + "does not guarantee in any particular instance" = three-level hedging.','hard'),
  (cid,73,229,'gap_fill','The _____ (findings) _____ (indicate) that _____ (institutional) _____ (capacity) _______ (may) be a _____ (more) _____ (significant) _____ (determinant) of _____ (reform) _____ (success) than _____ (formal) _____ (design) alone, _____ (though) this _____ (conclusion) _____ (warrant) _____ (further) _____ (empirical) _____ (test → noun).','findings / indicate / institutional / capacity / may / more / significant / determinant / reform / success / formal / design / though / conclusion / warrants / further / empirical / testing',NULL,'"Indicate that may be" = double hedge (verb + modal); "warrants further empirical testing" = methodological caveat.','hard'),
  (cid,73,230,'gap_fill','It _____ (appear) that the _____ (reform) _____ (has) _____ (achieve/passive) _____ (its) _____ (stated) _____ (objective) in some _____ (area), _____ (while) _____ (fall/gerund) _____ (short) in _____ (other) — a _____ (pattern) _____ _____ (suggest) that _____ (implementation) _____ (challenge) _____ (vary) _____ (considerably) _____ (across) _____ (different) _____ (element) of the _____ (program).','appears / reform / has / been achieved / its / stated / objectives / areas / while / falling / short / others / pattern / that / suggests / implementation / challenges / vary / considerably / across / different / elements / program',NULL,'"Appears," "pattern that suggests," "vary considerably" — multi-verb hedging across main and subordinate clauses.','hard'),
  (cid,73,231,'gap_fill','The _____ (author) _____ (seem) to _____ (imply) that _____ (structural) _____ (reform) is _____ (necessary) but _____ (not) _____ (sufficient) for _____ (improve/gerund) _____ (governance) _____ (quality) — _____ (a) _____ (position) _____ (that) _____ (align) _____ (with) _____ (much) _____ (of) _____ (the) _____ (contemporary) _____ (literature).','author / seems / imply / structural / reform / necessary / not / sufficient / improving / governance / quality / a / position / that / aligns / with / much / of / the / contemporary / literature',NULL,'"Seems to imply" = double hedge (seem + imply); "a position that aligns with" = attributed claim.','hard'),
  (cid,73,232,'gap_fill','These _____ (result) _____ (suggest) that the _____ (relationship) _____ (between) _____ (transparency) _____ (and) _____ (accountability) is _____ (more) _____ (complex) than _____ (previous) _____ (research) has _____ (imply/passive) — _____ (a) _____ (finding) that _____ (call) for _____ (more) _____ (nuanced) _____ (conceptual) _____ (framework).','results / suggest / relationship / between / transparency / and / accountability / more / complex / previous / research / implied / a / finding / that / calls / more / nuanced / conceptual / frameworks',NULL,'"Suggest" + "implied" (past hedge in previous literature) + "calls for" (prescriptive hedge).','hard'),
  (cid,73,233,'gap_fill','The _____ (evidence) _____ (tend) to _____ (support) the _____ (view) that _____ (governance) _____ (reform) is more _____ (likely) to _____ (succeed) in _____ (context) _____ (where) _____ (political) _____ (institution) are _____ (already) _____ (relatively) _____ (strong) — _____ (although) this _____ (raise) _____ (difficult) _____ (question) about _____ (how) _____ (to) _____ (begin) _____ (reform) in _____ (weaker) _____ (context).','evidence / tends / support / view / governance / reform / likely / succeed / contexts / where / political / institutions / already / relatively / strong / although / raises / difficult / questions / how / to / begin / reform / weaker / contexts',NULL,'"Tends to support the view that" + "more likely to succeed in contexts where" + "although this raises" — three hedges.','hard'),
  (cid,73,234,'multiple_choice','Which verb hedge is MOST appropriate? "The data _____ a positive correlation between civic education and trust in institutions."','suggest','["prove","confirm","demonstrate","suggest"]','All four can be used, but in academic writing "suggest" is most appropriate when discussing correlational data — it signals that the interpretation is one possible reading of the evidence.','medium'),

  -- BLOCK 74: Noun hedges (9 ex)
  (cid,74,235,'gap_fill','There is _____ (evidence) to _____ (suggest) that the _____ (rate) of institutional _____ (change) is _____ (determine/passive) _____ (in) _____ (part) by the _____ (strength) of _____ (vested) _____ (interest) — a _____ (finding) with _____ (important) _____ (implication) for the _____ (design) of _____ (reform) _____ (strategy).','evidence / suggest / rate / change / determined / in / part / strength / vested / interests / finding / important / implications / design / reform / strategies',NULL,'"There is evidence to suggest" = classic hedge phrase; "in part" = limiting phrase; "a finding with implications" = hedged conclusion.','medium'),
  (cid,74,236,'gap_fill','The _____ (possibility) that _____ (formal) _____ (structure) alone _____ (are) _____ (insufficient) to _____ (produce) _____ (effective) _____ (governance) _____ (deserve) _____ (serious) _____ (consideration), _____ (particularly) in _____ (light) _____ (of) _____ (the) _____ (growing) _____ (body) _____ (of) _____ (evidence) _____ (on) _____ (informal) _____ (institution).','possibility / formal / structures / are / insufficient / produce / effective / governance / deserves / serious / consideration / particularly / light / of / the / growing / body / of / evidence / on / informal / institutions',NULL,'"The possibility that" = noun hedge; "deserves serious consideration" = hedged recommendation.','medium'),
  (cid,74,237,'gap_fill','There is _____ (a) _____ (strong) _____ (indication) that the _____ (reform) has _____ (achieve/passive) _____ (some) _____ (of) _____ (its) _____ (objective), _____ (though) the _____ (extent) _____ (to) _____ (which) _____ (these) _____ (gain) are _____ (sustainable) _____ (remain) _____ (an) _____ (open) _____ (question).','a / strong / indication / reform / been achieved / some / of / its / objectives / though / extent / to / which / these / gains / sustainable / remains / an / open / question',NULL,'"A strong indication" + "though the extent remains an open question" = hedged positive + limiting caveat.','hard'),
  (cid,74,238,'gap_fill','The _____ (likelihood) of _____ (success) _____ (appear) to _____ (depend) on a _____ (number) of _____ (factor) that _____ (have) _____ (not) _____ (fully/understand/passive) — a _____ (gap) in _____ (understanding) that _____ (represent) both _____ (a) _____ (limitation) of the _____ (present) _____ (analysis) and _____ (a) _____ (fruitful) _____ (area) for _____ (future) _____ (research).','likelihood / success / appears / depend / number / factors / have / not / been fully understood / gap / understanding / represents / a / limitation / present / analysis / a / fruitful / area / future / research',NULL,'"The likelihood appears to depend" + "a gap that represents both a limitation and a fruitful area."','hard'),
  (cid,74,239,'gap_fill','There _____ (be) a _____ (suggestion) in the _____ (literature) that _____ (path) _____ (dependency) may _____ (limit) the _____ (range) of _____ (feasible) _____ (reform) _____ (option) _____ (available) to _____ (government) in _____ (any) _____ (particular) _____ (context) — _____ (though) this _____ (suggestion) _____ (require) _____ (further) _____ (empirical) _____ (examination).','is / suggestion / literature / path / dependency / limit / range / feasible / reform / options / available / governments / any / particular / context / though / suggestion / requires / further / empirical / examination',NULL,'"There is a suggestion in the literature that" + "though this suggestion requires further empirical examination" = framed + doubly hedged.','hard'),
  (cid,74,240,'gap_fill','The _____ (tendency) of _____ (bureaucracy) to _____ (resist) _____ (change) is _____ _____ (well-document/passive) in the _____ (literature), _____ (although) _____ (the) _____ (extent) to _____ _____ (which) this _____ (tendency) is _____ (universal) rather than _____ (context-specific) _____ (remain) _____ (unclear).','tendency / bureaucracies / resist / change / is / well-documented / literature / although / the / extent / to / which / tendency / universal / context-specific / remains / unclear',NULL,'"The tendency...is well-documented" acknowledged + "although the extent remains unclear" = limits the claim.','hard'),
  (cid,74,241,'gap_fill','The _____ (prospect) of _____ (achieve/gerund) _____ (significant) _____ (improve → noun) in _____ (governance) _____ (quality) within a _____ (short) _____ (timeframe) _____ (appear) to _____ (depend) critically on _____ (the) _____ (availability) of _____ (political) _____ (support) at the _____ (highest) _____ (level).','prospect / achieving / significant / improvement / governance / quality / short / timeframe / appears / depend / the / availability / political / support / highest / level',NULL,'"The prospect of achieving appears to depend" — noun hedge + verb hedge; "critically" intensifies without removing uncertainty.','hard'),
  (cid,74,242,'gap_fill','There _____ (be) _____ (some) _____ (indication) that _____ (decentralization) _____ (may) _____ (improve) _____ (service) _____ (delivery) in _____ (some) _____ (context), _____ (though) the _____ (condition) _____ (under) _____ (which) this _____ (occur) _____ (remain) _____ (insufficiently) _____ (understand/passive).','is / some / indication / decentralization / may / improve / service / delivery / some / contexts / though / conditions / under / which / occurs / remain / insufficiently / understood',NULL,'"Some indication that may improve" + "though the conditions remain insufficiently understood."','hard'),
  (cid,74,243,'multiple_choice','Which noun hedge phrase MOST effectively softens this claim? "Decentralization improves local service delivery."','There is evidence to suggest that decentralization may improve local service delivery in certain contexts.','["Decentralization definitely improves local service delivery.","There is evidence to suggest that decentralization may improve local service delivery in certain contexts.","Everyone knows decentralization improves local service delivery.","It is obvious that decentralization can improve local service delivery."]','Option B: "evidence to suggest," "may," "in certain contexts" = three hedges. Others use overconfident language.','easy'),

  -- BLOCK 75: Adjective hedges + frases hedging avançadas (9 ex)
  (cid,75,244,'gap_fill','It is _____ (possible) that the _____ (correlation) observed between these _____ (variable) reflects a _____ (common) underlying _____ (cause) rather than a _____ (direct) _____ (causal) _____ (link) — a _____ (possibility) that _____ (cannot) be _____ (exclude/passive) without _____ (more) _____ (rigorous) _____ (causal) _____ (analysis).','possible / correlation / variables / common / cause / direct / causal / link / possibility / cannot / excluded / more / rigorous / causal / analysis',NULL,'"It is possible that" + "a possibility that cannot be excluded" = noun and adjective hedge in combination.','medium'),
  (cid,75,245,'gap_fill','The _____ (likely) _____ (explanation) for the _____ (discrepancy) _____ (between) _____ (the) _____ (formal) _____ (mandate) and _____ (actual) _____ (practice) is _____ (a) _____ (combination) of _____ (misalign/passive) _____ (incentive) and _____ (insufficient) _____ (oversight) — _____ (though) _____ (other) _____ (interpretation) _____ (remain) _____ (plausible).','likely / explanation / discrepancy / between / the / formal / mandate / actual / practice / a / combination / misaligned / incentives / insufficient / oversight / though / other / interpretations / remain / plausible',NULL,'"The likely explanation" (adjective hedge) + "though other interpretations remain plausible" (caveating).','hard'),
  (cid,75,246,'gap_fill','To _____ (some) _____ (extent), the _____ (pattern) observed _____ (may) _____ (reflect) the _____ (specific) _____ (historical) and _____ (political) _____ (context) of the _____ (case) _____ (study/passive) rather than _____ (a) _____ (more) _____ (general) _____ (dynamic) — which _____ (would) _____ (limit) the _____ (generalize → noun) of the _____ (finding → noun).','some / extent / pattern / may / reflect / specific / historical / political / context / cases / studied / a / more / general / dynamic / would / limit / generalizability / findings',NULL,'"To some extent" + "may reflect" + "would limit generalizability" = three hedges on scope and certainty.','hard'),
  (cid,75,247,'gap_fill','It _____ (be) _____ (worth) _____ (note/gerund) that the _____ (sample) used in this _____ (analysis) _____ (may) _____ (not) be fully _____ (represent/adjective) of the _____ (broader) _____ (population) — a _____ (potential) _____ (limitation) that _____ (should) _____ (take/passive) _____ (into) _____ (account) when _____ (interpret/gerund) these _____ (finding → noun).','is / worth / noting / sample / may / not / representative / broader / population / potential / limitation / should / be taken / into / account / interpreting / findings',NULL,'"It is worth noting," "may not be fully representative," "potential limitation," "should be taken into account."','hard'),
  (cid,75,248,'gap_fill','The _____ (available) _____ (evidence) _____ (be) _____ (consistent) _____ (with) the _____ (interpretation) that _____ (informal) _____ (network) _____ (play) an _____ (important) _____ (role) in _____ (mediate/gerund) the _____ (relationship) _____ (between) _____ (formal) _____ (institution) and _____ (outcome) — _____ (though) this _____ (interpretation) _____ (require) _____ (direct) _____ (test → noun) to _____ (confirm/passive).','available / evidence / is / consistent / with / interpretation / informal / networks / play / important / role / mediating / relationship / between / formal / institutions / outcomes / though / interpretation / requires / direct / testing / be confirmed',NULL,'"Consistent with the interpretation that" + "though this interpretation requires direct testing to be confirmed" = two-hedge structure.','hard'),
  (cid,75,249,'gap_fill','Under _____ (certain) _____ (condition), the _____ (adoption) of _____ (formal) _____ (accountability) _____ (mechanism) _____ (appear) to _____ (generate) _____ (positive) _____ (feedback) _____ _____ (loop) that _____ (reinforce) _____ (their) _____ (effective → noun) — _____ (though) _____ (whether) this _____ (dynamic) _____ (apply) _____ (broadly) _____ (remain) _____ (unclear).','certain / conditions / adoption / formal / accountability / mechanisms / appears / generate / positive / feedback / loops / reinforce / effectiveness / though / whether / dynamic / applies / broadly / remains / unclear',NULL,'"Under certain conditions" + "appears to generate" + "though whether this dynamic applies broadly remains unclear."','hard'),
  (cid,75,250,'gap_fill','This _____ (analysis) _____ (represent) _____ (a) _____ (preliminary) _____ (attempt) to _____ (address) _____ (a) _____ (complex) _____ (question) and _____ (should) _____ (read/passive) _____ (as) _____ (such) — _____ (the) _____ (finding → noun) _____ (report/passive) _____ (here) _____ (be) _____ (suggestive) rather than _____ (conclusive) and _____ (require) _____ (significant) _____ (further) _____ (work) to _____ (validate/passive).','analysis / represents / a / preliminary / attempt / address / a / complex / question / should / be read / as / such / the / findings / reported / here / are / suggestive / conclusive / require / significant / further / work / be validated',NULL,'"Preliminary attempt," "should be read as such," "suggestive rather than conclusive," "require significant further work to be validated" = multiple methodological hedges.','hard'),
  (cid,75,251,'gap_fill','_____ (A) _____ (tentative) _____ (conclusion) that _____ (emerge) from this _____ (analysis) is that _____ (governance) _____ (reform) _____ (is) _____ (unlikely) to _____ (succeed) without _____ (sustained) _____ (political) _____ (support) — _____ (a) _____ (conclusion), _____ (it) _____ (should) _____ (note/passive), that _____ (is) _____ (not) _____ (unique) to this _____ (study).','A / tentative / conclusion / emerges / analysis / governance / reform / is / unlikely / succeed / sustained / political / support / a / conclusion / it / should / be noted / is / not / unique / study',NULL,'"A tentative conclusion" = adjective hedge; "it should be noted" = parenthetical hedge; "not unique to this study" = literature grounding.','hard'),
  (cid,75,252,'multiple_choice','Which phrase MOST effectively hedges the scope of a finding in academic writing?','To some extent, the pattern observed may reflect context-specific factors rather than a general dynamic.','["The pattern observed definitely reflects context-specific factors.","To some extent, the pattern observed may reflect context-specific factors rather than a general dynamic.","Obviously the pattern reflects context-specific factors.","The pattern must reflect context-specific factors, not general ones."]','Option B: "to some extent" (scope) + "may reflect" (modal) + "rather than" (contrast) = three hedges. Others use overconfident markers.','easy'),

  -- BLOCK 76: Degrees of certainty — calibração (8 ex)
  (cid,76,253,'gap_fill','The _____ (evidence) _____ (clearly/adverb) _____ (demonstrate) that _____ (institutional) _____ (quality) _____ (matter → noun), but _____ (consider → noun) _____ (uncertainty) _____ (remain) about the _____ (precise) _____ (mechanism) _____ (through) _____ (which) it _____ (exert) its _____ (influence).','evidence / clearly / demonstrates / institutional / quality / matters / considerable / uncertainty / remains / precise / mechanisms / through / which / exerts / influence',NULL,'"Clearly demonstrates" (high certainty) + "considerable uncertainty remains about the precise mechanisms" = appropriate calibration.','hard'),
  (cid,76,254,'gap_fill','While it _____ (certainly) _____ (be) _____ (the) _____ (case) that _____ (some) _____ (reform) _____ (have) _____ (succeed), _____ (it) _____ (is) _____ (less) _____ (clear) _____ (whether) the _____ (success) can _____ (attribute/passive) to _____ (formal) _____ (design) rather than to _____ (favorable) _____ (circumstance).','certainly / is / the / case / some / reforms / have / succeeded / it / is / less / clear / whether / success / be attributed / formal / design / favorable / circumstances',NULL,'"Certainly is the case" (concedes a point) + "it is less clear whether" (pivots to uncertainty) = contrast calibration.','hard'),
  (cid,76,255,'gap_fill','There _____ (is) _____ (little) _____ (doubt) that _____ (transparency) _____ (matter) for _____ (accountability), _____ (but) _____ (the) _____ (precise) _____ (form) it _____ (should) _____ (take) in _____ (any) _____ (given) _____ (context) _____ (remains) _____ (open) _____ (to) _____ (debate).','is / little / doubt / transparency / matters / accountability / but / the / precise / form / should / take / any / given / context / remains / open / to / debate',NULL,'"There is little doubt" (near-certainty) + "the precise form remains open to debate" (uncertainty on application).','medium'),
  (cid,76,256,'gap_fill','It _____ (seem) _____ (probable) that _____ (the) _____ (reform) will _____ (produce) _____ (some) _____ (measurable) _____ (improvement), _____ (though) _____ (it) is _____ (less) _____ (certain) _____ (whether) the _____ (improvement) will be _____ (sufficient) to _____ (justify) the _____ (significant) _____ (invest → noun) _____ (require/passive).','seems / probable / the / reform / produce / some / measurable / improvement / though / it / less / certain / whether / improvement / sufficient / justify / significant / investment / required',NULL,'"Seems probable" (moderate certainty) + "less certain whether sufficient" (lower certainty on degree).','hard'),
  (cid,76,257,'gap_fill','The _____ (conclusion) that _____ (institutional) _____ (reform) is _____ (necessary) for _____ (sustainable) _____ (development) _____ (is) _____ (relatively) _____ (well-establish/passive), _____ (whereas) the _____ (conclusion) that _____ (it) is _____ (sufficient) _____ (is) _____ (consider/passive) _____ (far) _____ (more) _____ (contest/adjective).','conclusion / institutional / reform / necessary / sustainable / development / is / relatively / well-established / whereas / conclusion / sufficient / is / considered / far / more / contested',NULL,'"Relatively well-established" (moderate certainty) vs "considered far more contested" (low certainty) = explicit calibration contrast.','hard'),
  (cid,76,258,'gap_fill','The _____ (overall) _____ (picture) that _____ (emerge) from this _____ (analysis) is _____ (nuance/adjective) but _____ (broadly) _____ (optimistic) — _____ (progress) _____ (is) _____ (possible), _____ (although) _____ (it) _____ (will) _____ (require) _____ (sustained) _____ (effort) and _____ (realistic) _____ (expectation) about _____ (the) _____ (pace) of _____ (change).','overall / picture / emerges / analysis / nuanced / broadly / optimistic / progress / is / possible / although / it / will / require / sustained / effort / realistic / expectations / the / pace / change',NULL,'"Nuanced but broadly optimistic" + "progress is possible, although will require" = hedged positive conclusion.','hard'),
  (cid,76,259,'gap_fill','The _____ (field) has _____ (come) a _____ (long) _____ (way) in _____ (understand/gerund) _____ (governance) _____ (reform), but it _____ (would) _____ (be) _____ (premature) to _____ (claim) that _____ (all) _____ (the) _____ (major) _____ (question) _____ (have) _____ (resolve/passive).','field / come / long / way / understanding / governance / reform / would / be / premature / claim / all / the / major / questions / have / been resolved',NULL,'"It would be premature to claim" = classic hedging phrase signaling limits of current knowledge.','medium'),
  (cid,76,260,'multiple_choice','Which sentence MOST effectively calibrates certainty in academic writing?','The evidence strongly suggests that transparency matters, though the conditions under which it translates into accountability remain less well understood.','["Transparency definitely causes accountability in all contexts.","Transparency might perhaps possibly affect accountability to some degree.","The evidence strongly suggests that transparency matters, though the conditions under which it translates into accountability remain less well understood.","It is obvious that transparency leads to accountability."]','Option C: "strongly suggests" (high but hedged) + "remain less well understood" (honest uncertainty) = perfect calibration. Option A overconfident; Option B over-hedged; Option D removes hedge.','medium'),

  -- BLOCK 77: TOEFL Reading — Hedging Language (8 ex)
  (cid,77,261,'multiple_choice','[TOEFL Reading] "The evidence may suggest that decentralization improves service delivery, though this relationship appears to be context-dependent." The words "may suggest" and "appears to be" are examples of:','hedging language that expresses epistemic caution.','["rhetorical questions","hedging language that expresses epistemic caution.","transition words","absolute claims"]','Both "may suggest" and "appears to be" signal uncertainty — characteristic hedging in academic writing.','easy'),
  (cid,77,262,'gap_fill','[TOEFL Reading] "The _____ (tend → noun) of institutions to resist change is well-_____ (document/passive), _____ (although) the _____ (extent) to which this _____ (is) universal _____ (remain) unclear." What do the underlined hedging elements add?','tendency / documented / although / extent / remains',NULL,'"Tendency" (noun hedge), "well-documented" (qualified with "well"), "although the extent remains unclear" (concessive caveat).','medium'),
  (cid,77,263,'gap_fill','[TOEFL Reading] "There is _____ (some) _____ (indication) that path dependency _____ (may) limit the range of feasible reform _____ (option), though this _____ (suggestion) _____ (require) further empirical _____ (examine → noun)." What are the hedging devices?','some / indication / may / options / suggestion / requires / examination',NULL,'"Some indication" (noun hedge), "may limit" (modal), "though this suggestion requires further examination" (caveat).','medium'),
  (cid,77,264,'gap_fill','[TOEFL Reading] "It _____ (would) _____ (appear) that formal rules alone are _____ (insufficient) to produce effective governance." The phrase "it would appear that" is a hedge because:','it conveys that the claim is based on appearance rather than certainty',NULL,'"It would appear that" = distancing phrase; modal "would" + "appear" = double-layer hedge signaling inference from evidence, not proven fact.','medium'),
  (cid,77,265,'gap_fill','[TOEFL Reading] "_____ (Argue/adverb), the most important factor is political will rather than institutional design." The epistemic adverb is:','Arguably',NULL,'"Arguably" acknowledges that the claim is debatable — the writer''s position but one others might contest.','easy'),
  (cid,77,266,'gap_fill','[TOEFL Reading] "The reform _____ (tend) to _____ (succeed) when _____ (accompany/passive) by sustained political will — _____ (a) _____ (pattern) that _____ (emerge/past) consistently across the cases studied but that _____ (not/guarantee) success in any _____ (particular) instance." The hedging devices are:','tends / succeed / accompanied / a / pattern / emerged / does not guarantee / particular',NULL,'"Tends to succeed" (not "always succeeds"), "pattern that emerged" (evidential), "does not guarantee in any particular instance" (explicit caveat).','hard'),
  (cid,77,267,'gap_fill','[TOEFL Reading] "To _____ (some) _____ (extent), the _____ (pattern) observed _____ (may) reflect context-specific factors rather than a _____ (general) _____ (dynamic)." The phrase "to some extent" is a:','scope-limiting hedge','["scope-limiting hedge","absolute claim","transition word","causal conjunction"]','"To some extent" limits how much of the pattern is attributed to context — a hedge on scope, not certainty.','easy'),
  (cid,77,268,'multiple_choice','[TOEFL Reading] "This analysis represents a preliminary attempt to address a complex question and should be read as such — the findings reported here are suggestive rather than conclusive." The hedging function of "suggestive rather than conclusive" is:','to explicitly limit the strength of the claim being made.','["to make the claim more persuasive","to explicitly limit the strength of the claim being made.","to show confidence in the findings","to transition to the next point"]','"Suggestive rather than conclusive" explicitly downgrades the epistemic status of the findings — a strong methodological hedge.','easy'),

  -- BLOCK 78: TOEFL Speaking — Hedging Language (8 ex)
  (cid,78,269,'production','[TOEFL Speaking — 45s] Summarize a reading on institutional reform using hedging language throughout.','',NULL,'The reading examines the conditions under which institutional reform leads to sustained improvement in governance, and it suggests — though it does not claim to have resolved the question definitively — that several factors appear to be particularly important. The evidence seems to indicate that reform is more likely to succeed when it is accompanied by sustained political will, though the reading acknowledges that establishing a causal relationship between political will and reform success is methodologically challenging. The author concludes that the findings are broadly consistent with existing literature, while noting that considerable uncertainty remains about the mechanisms through which design choices translate into outcomes. The reading appears to argue that further research is needed before firm policy prescriptions can be justified.','hard'),
  (cid,78,270,'production','[TOEFL Speaking — 45s] The professor challenges the reading. Use hedging language throughout.','',NULL,'The professor appears to be largely skeptical of the reading''s conclusions, though she does not seem to reject them entirely. She suggests that the reading may have overestimated the importance of formal institutional design and underestimated the role of informal norms and political economy. The evidence she presents, while not conclusive on its own, tends to support the view that the relationship between design and outcomes is more complex than the reading implies. She seems to argue that it would be premature to draw strong policy conclusions from the available evidence, and that what may be needed is not better institutional design but a more sophisticated understanding of the conditions under which different design choices produce different outcomes.','hard'),
  (cid,78,271,'production','[TOEFL Speaking — 60s] Compare reading and professor on the determinants of reform success, using hedging language throughout.','',NULL,'The reading and the professor appear to offer complementary rather than contradictory perspectives on the determinants of reform success, though they do seem to differ in their assessment of which factors matter most. The reading tends to emphasize technical dimensions — the quality of institutional design, the adequacy of implementation capacity, and the availability of performance measurement systems — and suggests that getting these elements right may be a necessary condition for success. The professor, by contrast, seems to argue that these technical factors, while important, are arguably insufficient on their own. Her evidence tends to support the view that the political economy of reform — the organization of support and opposition and the management of the transition process — may be at least as important as technical design in determining whether reform achieves its objectives. It would appear that both perspectives have merit, and that the most realistic assessment may be that success requires attention to both dimensions simultaneously. The relationship between the two, however, remains less than fully understood, and it would be premature to conclude that either perspective alone provides a sufficient account of what determines whether governance reform succeeds or fails.','hard'),
  (cid,78,272,'gap_fill','[TOEFL Speaking] The evidence _____ (seem) to _____ (suggest) that governance reform _____ (is) _____ (likely) to _____ (require) sustained political commitment — _____ (though) _______ (considerable) uncertainty _____ (remains) about the precise conditions under which such commitment can _____ (sustain/passive).','seems / suggest / is / likely / require / though / considerable / remains / be sustained',NULL,'"Seems to suggest" + "is likely to require" + "though considerable uncertainty remains" + "can be sustained" (passive hedge).','hard'),
  (cid,78,273,'gap_fill','[TOEFL Speaking] _____ (Arguably), the _____ (most) _____ (significant) _____ (finding) _____ (emerge/passive) from this _____ (analysis) _____ (be) that _____ (formal) _____ (design) _____ (alone) _____ (be) _____ (insufficient) to _____ (produce) _____ (effective) _____ (governance) — _____ (though) _____ (this) _____ (conclusion) _____ (remain) _____ (tentative/adverb) _____ (state/passive) until _____ (further) _____ (evidence) _____ (accumulate/passive).','Arguably / most / significant / finding / emerging / analysis / is / formal / design / alone / is / insufficient / produce / effective / governance / though / this / conclusion / remains / tentatively / stated / further / evidence / has accumulated',NULL,'"Arguably" + "the most significant finding" + "though this conclusion remains tentatively stated until further evidence has accumulated" = calibrated hedging.','hard'),
  (cid,78,274,'gap_fill','[TOEFL Speaking] There _____ (be) a _____ (possibility) that the _____ (failure) _____ (of) _____ (previous) _____ (reform) _____ (was) due not to poor _____ (design) but to _____ (insufficient) _____ (attention) to _____ (implementation) — _____ (a) _____ (possibility) that _____ (deserve) serious _____ (consideration).','is / possibility / failure / of / previous / reforms / was / design / insufficient / attention / implementation / a / possibility / deserves / consideration',NULL,'"There is a possibility that" + "a possibility that deserves serious consideration" = framed and reinforced noun hedge.','medium'),
  (cid,78,275,'gap_fill','[TOEFL Speaking] It _____ (might) _____ (be) _____ (worth) _____ (note/gerund) that the _____ (sample) used in this _____ (analysis) _____ (may) not _____ (be) fully _____ (represent/adjective) of the _____ (broader) _____ (population), _____ (which) _____ (could) _____ (limit) the _____ (generalize → noun) of the _____ (find → noun).','might / be / worth / noting / sample / analysis / may / be / representative / broader / population / which / could / limit / generalizability / findings',NULL,'"Might be worth noting," "may not be fully representative," "could limit generalizability" = three-layer methodological hedge.','hard'),
  (cid,78,276,'multiple_choice','[TOEFL Speaking] Which response MOST appropriately hedges a claim about governance reform?','The evidence seems to suggest that decentralization may improve service delivery, though the conditions under which this occurs remain somewhat unclear.','["Decentralization always improves service delivery.","The evidence seems to suggest that decentralization may improve service delivery, though the conditions under which this occurs remain somewhat unclear.","I think decentralization is good for service delivery.","It is obvious that decentralization leads to better services."]','Option B: "seems to suggest," "may improve," "though...remain somewhat unclear" = appropriate academic hedging for TOEFL Speaking.','easy'),

  -- BLOCK 79: TOEFL Writing — produção avançada (8 ex)
  (cid,79,277,'production','[TOEFL Writing — 200 words] Write a body paragraph on the limitations of institutional design using hedging language throughout.','',NULL,'There is considerable evidence to suggest that formal institutional design, while important, may be insufficient on its own to produce effective governance — a conclusion that appears to be broadly consistent with the available comparative literature, though the precise mechanisms remain less than fully understood. The possibility that informal norms and political incentives play a more significant role than formal rules in determining organizational behavior deserves serious consideration, particularly in light of the growing body of evidence from institutionalist research suggesting that behavior tends to reflect informal incentives rather than formal mandates when the two diverge. It would appear that the assumption of self-enforcing rules, which seems to underlie much formal institutional design, is likely to prove overly optimistic in contexts where the interests of those charged with enforcement diverge from the objectives the rules are designed to achieve. This analysis represents a preliminary attempt to address a complex question and should be read as such — the findings reported here are suggestive rather than conclusive and require significant further work to establish with the degree of rigor that firm policy prescriptions would demand.','hard'),
  (cid,79,278,'production','[TOEFL Writing — 200 words] Write a body paragraph on the measurement of governance outcomes using hedging language.','',NULL,'The measurement of governance outcomes appears to be considerably more difficult than the design of governance reforms, suggesting that the monitoring and evaluation systems that are essential to adaptive management may themselves represent a significant constraint on the effectiveness of reform programs. There is some indication in the literature that the availability of reliable outcome data tends to improve the quality of governance decisions, though the relationship between measurement capacity and governance performance is arguably more complex than this simple observation implies. It would be premature to conclude, on the basis of currently available evidence, that investment in measurement capacity is a sufficient condition for improved governance outcomes — the likelihood of success appears to depend on a range of complementary factors, including the political will to act on evidence that may be inconvenient, the organizational capacity to translate measurement findings into operational adjustments, and the existence of feedback mechanisms that allow learning to accumulate over time. The overall picture that emerges from this analysis is nuanced but broadly consistent with the view that measurement matters, though the precise conditions under which its benefits are realized remain less than fully specified in the existing literature.','hard'),
  (cid,79,279,'gap_fill','[TOEFL Writing] The _____ (evidence) _____ (strongly/adverb) _____ (suggest) that _____ (transparency) _____ (matter), _____ (though) the _____ (condition) under which it _____ (translate) into _____ (accountability) _____ (remain) less _____ (well/adverb) _____ (understand/passive).','evidence / strongly / suggests / transparency / matters / though / conditions / translates / accountability / remain / well / understood',NULL,'"Strongly suggests" (high but hedged) + "though conditions remain less well understood" = calibrated academic claim.','medium'),
  (cid,79,280,'gap_fill','[TOEFL Writing] _____ (Arguably), the _____ (most) _____ (significant) _____ (insight) _____ (to) _____ (emerge) from this _____ (analysis) is that _____ (governance) _____ (reform) _____ (cannot/treat/passive) as _____ (a) _____ (technical) _____ (problem) with _____ (a) _____ (determinant/adjective) _____ (solution).','Arguably / most / significant / insight / to / emerge / analysis / governance / reform / cannot be treated / a / technical / problem / a / determinate / solution',NULL,'"Arguably" + "cannot be treated" = normative hedge on conceptual framing.','hard'),
  (cid,79,281,'gap_fill','[TOEFL Writing] It _____ (would) _____ (be) _____ (premature) to _____ (conclude) that all the _____ (major) _____ (question) about _____ (governance) _____ (reform) _____ (resolve/passive) — _____ (considerable) _____ (uncertainty) _____ (remain) and _____ (likely) _____ (will) _____ (persist) for some _____ (time).','would / be / premature / conclude / major / questions / governance / reform / have been resolved / considerable / uncertainty / remains / likely / will / persist / time',NULL,'"It would be premature to conclude" + "considerable uncertainty remains and likely will persist" = two hedges on knowledge status.','medium'),
  (cid,79,282,'gap_fill','[TOEFL Writing] The _____ (overall) _____ (conclusion) that _____ (emerge) from this _____ (analysis) — that _____ (governance) _____ (reform) _____ (is) _____ (possible) but _____ (difficult) — _____ (be) _____ (tentative/adverb) _____ (offer/passive) and _____ (should) _____ (take/passive) as a _____ (starting) _____ (point) for _____ (further) _____ (investigation) rather than as a _____ (definitive) _____ (conclusion).','overall / conclusion / emerges / analysis / governance / reform / is / possible / difficult / is / tentatively / offered / should / be taken / starting / point / further / investigation / definitive / conclusion',NULL,'"Tentatively offered" + "should be taken as a starting point rather than a definitive conclusion" = explicit epistemic modesty.','hard'),
  (cid,79,283,'gap_fill','[TOEFL Writing] This _____ (paper) _____ (has) _____ (attempt/passive) to _____ (contribute) to _____ (our) _____ (understand/gerund → noun) of _____ (governance) _____ (reform), _____ (though) _____ (it) _____ (would) _____ (be) _____ (the) _____ (first) _____ (to) _____ (acknowledge) that _____ (significant) _____ (gap) in _____ (knowledge) _____ (remain).','paper / has / attempted / contribute / our / understanding / governance / reform / though / it / would / be / the / first / acknowledge / significant / gaps / knowledge / remain',NULL,'"This paper has attempted to contribute" (hedged contribution claim) + "would be the first to acknowledge that gaps remain" (epistemic modesty).','hard'),
  (cid,79,284,'multiple_choice','[TOEFL Writing] Which closing sentence MOST effectively hedges a paper''s overall conclusion?','The analysis suggests that governance reform is more likely to succeed under certain conditions than others, though the precise nature of those conditions remains an important question for future research.','["This paper proves that governance reform always succeeds under the right conditions.","The analysis clearly shows that governance reform succeeds when conditions are right.","The analysis suggests that governance reform is more likely to succeed under certain conditions than others, though the precise nature of those conditions remains an important question for future research.","Obviously governance reform is difficult and depends on conditions."]','Option C: "suggests," "more likely," "though...remains an important question for future research" = three hedges in one closing sentence.','medium'),

  -- BLOCK 80: Produção avançada — hedging completo (8 ex)
  (cid,80,285,'production','[TOEFL Writing — 200 words] Write a conclusion on what the analysis has tentatively established using hedging language throughout.','',NULL,'The analysis presented in this paper has attempted to illuminate the conditions under which governance reform is more likely to succeed — a question that appears to be both analytically tractable and practically important, though it would be premature to suggest that the work done here resolves it definitively. The findings reported are broadly consistent with the view that reform success tends to depend on a combination of technical and political factors, though the precise nature of this combination and the mechanisms through which the two interact remain less than fully understood. There is evidence to suggest that formal institutional design matters, though it seems unlikely to be sufficient on its own — a conclusion that appears to imply the need for greater attention to the political economy of reform and the informal dimensions of organizational behavior. It would be overstating the case to claim that these tentative conclusions constitute a reliable guide to governance reform practice, but it would equally be understating them to dismiss them as having no practical relevance. The most accurate characterization may be that they represent a useful starting point for further inquiry — a contribution, however modest, to the accumulation of knowledge about one of the most important and difficult challenges in contemporary governance.','hard'),
  (cid,80,286,'gap_fill','[TOEFL Writing] The _____ (finding → noun) _____ (report/passive) in this _____ (paper) _____ (be) _____ (suggestive) rather than _____ (conclusive) and _____ (should) _____ (interpret/passive) _____ (with) _____ (appropriate) _____ (caution) — _____ (significant) _____ (further) _____ (work) _____ (be) _____ (need/passive) before _____ (firm) _____ (policy) _____ (prescription) _____ (can) _____ (justify/passive).','findings / reported / paper / are / suggestive / conclusive / should / be interpreted / with / appropriate / caution / significant / further / work / is / needed / firm / policy / prescriptions / can / be justified',NULL,'"Suggestive rather than conclusive," "should be interpreted with appropriate caution," "significant further work is needed."','hard'),
  (cid,80,287,'gap_fill','[TOEFL Writing] _____ (While) _____ (the) _____ (evidence) _____ (be) _____ (broadly → adverb) _____ (consistent) _____ (with) _____ (the) _____ (interpret → noun) _____ (that) _____ (informal) _____ (norm) _____ (matter), _____ (it) _____ (would) _____ (be) _____ (overstate/gerund) _____ (the) _____ (case) _____ (to) _____ (claim) _____ (that) _____ (formal) _____ (structure) _____ (be) _____ (irrelevant).','While / the / evidence / is / broadly / consistent / with / the / interpretation / that / informal / norms / matter / it / would / be / overstating / the / case / to / claim / that / formal / structures / are / irrelevant',NULL,'"Broadly consistent with the interpretation that" + "it would be overstating the case to claim that" = double hedge maintaining balance.','hard'),
  (cid,80,288,'gap_fill','[TOEFL Writing] A _____ (tentative) _____ (conclude → noun) that _____ (can) _____ (draw/passive) from _____ (this) _____ (analysis) is that _____ (invest → noun) in _____ (institutional) _____ (capacity) _____ (appear) to be _____ (necessary) but _____ (not) _____ (sufficient) for _____ (sustain/adjective) _____ (improve → noun) in _____ (governance) _____ (quality).','tentative / conclusion / can / be drawn / this / analysis / investment / institutional / capacity / appears / necessary / not / sufficient / sustained / improvement / governance / quality',NULL,'"A tentative conclusion that can be drawn" + "appears to be necessary but not sufficient" = hedged causal claim.','hard'),
  (cid,80,289,'gap_fill','[TOEFL Writing] The _____ (overall) _____ (picture) that _____ (emerge) is _____ (nuance/adjective) — _____ (progress) _____ (is) _____ (possible), but _____ (the) _____ (condition) _____ (under) which it _____ (occur) _____ (remain) _____ (incompletely → adverb) _____ (specify/passive) and _____ (therefore) _____ (warrant) _____ (further) _____ (empirical) _____ (investigate → noun).','overall / picture / emerges / nuanced / progress / is / possible / the / conditions / under / occurs / remain / incompletely / specified / therefore / warrant / further / empirical / investigation',NULL,'"Nuanced," "progress is possible," "remain incompletely specified," "warrant further empirical investigation" = calibrated closing hedge.','hard'),
  (cid,80,290,'production','[TOEFL Writing — 200 words] Write a paragraph on governance and uncertainty using hedging language throughout.','',NULL,'Uncertainty appears to be an inherent feature of governance — not merely a methodological limitation to be overcome but a fundamental characteristic of the environments in which governance occurs and the problems it is designed to address. The complexity of social systems seems to ensure that the consequences of governance choices will always be, at least in part, unpredictable — a recognition that has important implications for how we think about the design of governance frameworks and the expectations we hold about their performance. There is evidence to suggest that governance systems that are designed with uncertainty in mind — that incorporate feedback mechanisms, encourage experimentation, and maintain adaptive capacity — tend to perform more effectively over time than those designed on the assumption that the consequences of policy choices can be predicted with precision. It would, however, be overstating the case to claim that adaptive design is a sufficient condition for effective governance under uncertainty. The likelihood of success appears to depend also on the quality of leadership, the strength of organizational culture, and the availability of political support for learning and adaptation — factors whose relative importance may vary considerably across contexts and whose interaction remains incompletely understood.','hard'),
  (cid,80,291,'gap_fill','[TOEFL Writing] The _____ (analysis) _____ (suggest) that _____ (reform) _____ (success) _____ (tend) to _____ (depend) on a _____ (number) of _____ (condition) whose _____ (precise) _____ (nature) _____ (remain) an _____ (important) _____ (question) for _____ (future) _____ (research) — _____ (a) _____ (conclusion) _____ (consistent) with the _____ (view) that _____ (governance) _____ (is) _____ (inherent/adverb) _____ (complex).','analysis / suggests / reform / success / tends / depend / number / conditions / precise / nature / remains / important / question / future / research / a / conclusion / consistent / view / governance / is / inherently / complex',NULL,'"Suggests that tends to depend," "remains an important question," "consistent with the view that inherently complex" = dense hedging.','hard'),
  (cid,80,292,'multiple_choice','[TOEFL Writing] Which sentence MOST effectively hedges a conclusion in an integrated essay?','The evidence tends to support the professor''s position, though the reading raises considerations that complicate a straightforward acceptance of that view.','["The professor is right and the reading is wrong.","Both the professor and the reading are correct in all respects.","The evidence tends to support the professor''s position, though the reading raises considerations that complicate a straightforward acceptance of that view.","Obviously the professor''s argument is better than the reading''s."]','Option C: "tends to support" + "though the reading raises considerations" + "complicate a straightforward acceptance" = nuanced hedging of comparative claim.','medium'),

  -- BLOCK 81: Capstone final (9 ex)
  (cid,81,293,'production','[TOEFL Writing — 200 words] Final capstone: Write a concluding paragraph using hedging language throughout.','',NULL,'The analysis presented in this paper suggests — tentatively, and with the appropriate acknowledgment that significant uncertainty remains — that governance reform is possible, that it depends on a combination of technical and political factors that appear to interact in complex ways, and that the conditions under which it succeeds are more contextually specific than general models imply. It would be premature to offer this as a definitive account of what determines whether reform succeeds or fails; the evidence available is consistent with this interpretation but does not compel it, and alternative explanations cannot be ruled out without more rigorous causal analysis than the available data permit. The overall picture that emerges is perhaps best characterized as one of cautious optimism: progress appears to be achievable under the right conditions, and our understanding of what those conditions are seems to be improving — though the pace of that improvement may be slower than the urgency of the governance challenges we face would ideally require. What seems clear, if nothing else, is that the question of how to build and sustain effective governance institutions deserves the sustained attention of scholars, practitioners, and citizens alike, and that the investment in answering it better is likely to prove worthwhile.','hard'),
  (cid,81,294,'gap_fill','[TOEFL Writing] The _____ (conclusion) of this _____ (paper) — that _____ (governance) _____ (reform) _____ (is) _____ (possible) but _____ (difficult) — _____ (be) _____ (offer/passive) _____ (tentative/adverb) and _____ (should) _____ (understand/passive) _____ (as) _____ (a) _____ (start → noun) _____ (point) rather than _____ (a) _____ (definitive) _____ (resolution) of the _____ (question) _____ (address/passive).','conclusion / paper / governance / reform / is / possible / difficult / is / offered / tentatively / should / be understood / a / starting / point / a / definitive / resolution / question / addressed',NULL,'"Offered tentatively," "should be understood as a starting point," "rather than a definitive resolution" = modestly framed closing.','hard'),
  (cid,81,295,'gap_fill','[TOEFL Writing] The _____ (field) _____ (has) _____ (make/passive) _____ (progress), but _____ (it) _____ _____ (would) _____ (be) _____ (overstate/gerund) the _____ (case) to _____ (suggest) that _____ (the) _____ (answer) to the _____ (most) _____ (important) _____ (question) about _____ (governance) _____ (reform) _____ (are) _____ (now) _____ (clear).','field / has / been made / progress / it / would / be / overstating / case / suggest / the / answers / most / important / questions / governance / reform / are / now / clear',NULL,'"It would be overstating the case to suggest that the answers are now clear" = classic epistemic caution phrase.','hard'),
  (cid,81,296,'gap_fill','[TOEFL Writing] _____ (Arguably), the _____ (most) _____ (important) _____ (contribution) this _____ (analysis) _____ (can) _____ (make) is to _____ (clarify) what _____ (we) _____ (do) and _____ (do) _____ (not) _____ (yet) _____ (know) about _____ (governance) _____ (reform) — a _____ (modest) _____ (goal), but _____ (one) that _____ (seem) _____ _____ (consistent) with _____ (the) _____ (current) _____ (state) of _____ (knowledge).','Arguably / most / important / contribution / analysis / can / make / clarify / we / do / do / not / yet / know / governance / reform / modest / goal / one / seems / consistent / the / current / state / knowledge',NULL,'"Arguably the most important contribution" + "a modest goal but one that seems consistent with current state of knowledge."','hard'),
  (cid,81,297,'gap_fill','[TOEFL Writing] The _____ (question) of _____ (how) to _____ (build) _____ (effective) _____ (governance) _____ (institution) _____ (remain) _____ (partially/adverb) _____ (answer/passive) — _____ (a) _____ (recognition) that _____ (should) _____ (motivate) _____ (further) _____ (invest → noun) in _____ (research) rather than _____ (discourage) it.','question / how / build / effective / governance / institutions / remains / partially / answered / a / recognition / should / motivate / further / investment / research / discourage',NULL,'"Remains partially answered" (honest epistemic status) + "a recognition that should motivate" = hedged but forward-looking close.','hard'),
  (cid,81,298,'production','[TOEFL Writing — 200 words] Write a final paragraph on what future research should acknowledge about its limitations.','',NULL,'Future research in this area would do well to acknowledge, from the outset, the significant methodological challenges that appear to be inherent in the study of governance reform. The measurement of governance quality remains contested and imprecise; the identification of causal mechanisms connecting formal institutional change to behavioral outcomes is methodologically demanding; and the generalization of findings from particular cases to broader populations of contexts is constrained by the context-specificity of governance dynamics in ways that are not yet well understood. These are not reasons to abandon the enterprise of governance research — the practical importance of the questions it addresses seems to more than justify the investment — but they are reasons to be cautious about the strength of the claims that can reasonably be made on the basis of any particular study. There is a tendency in the literature, perhaps understandable given the pressures of academic publishing, to claim more certainty than the evidence warrants — a tendency that this paper has attempted to resist, though it would be naive to suggest that it has succeeded entirely. What seems clear is that the field would benefit from more explicit and systematic attention to the limitations of current methods and to the conditions under which different methodological approaches are likely to produce reliable results.','hard'),
  (cid,81,299,'gap_fill','[TOEFL Writing] What _____ (seem) _____ (clear), if _____ (nothing) _____ (else), is that _____ (the) _____ (question) of _____ (how) to _____ (build) _____ (effective) _____ (governance) _____ (institution) _____ (deserve) the _____ (sustain/adjective) _____ (attention) of _____ (scholar), _____ (practitioner), and _____ (citizen) _____ (alike).','seems / clear / nothing / else / the / question / how / build / effective / governance / institutions / deserves / sustained / attention / scholars / practitioners / citizens / alike',NULL,'"What seems clear, if nothing else" = qualified certainty hedge before a positive claim; "sustained attention" reinforces the forward-looking message.','medium'),
  (cid,81,300,'production','[TOEFL Writing — Final 200 words] Write a final hedged concluding paragraph on governance research and its implications for practice.','',NULL,'The relationship between governance research and governance practice is itself a subject on which there appears to be more uncertainty than the confident prescriptions that often emerge from academic literature might suggest. The translation of research findings into policy-relevant guidance requires not only that the findings be reliable — which is itself uncertain — but that the conditions under which they apply be specified with a precision that tends to exceed what the available evidence supports. This is not an argument against the practical relevance of governance research; there seems little doubt that better understanding of what makes governance work tends to produce better governance practice, at least at the margins. But it is an argument for epistemic modesty — for acknowledging that what we think we know may be less firmly established than we believe, that the conditions under which our findings apply may be more limited than we recognize, and that the policy implications we draw may be more contestable than we acknowledge. This paper has attempted to model this kind of epistemic modesty throughout, in the hope that doing so represents a more honest and ultimately more useful contribution to the accumulation of knowledge about governance than the alternative of overstating what can currently be known.','hard')

